        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] == color and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append((color, cells))

    # Find the L-shaped component that reaches two adjacent edges.
    marker = None
    for color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        edges = []
        if r0 == 0: edges.append("top")
        if r1 == h - 1: edges.append("bottom")
        if c0 == 0: edges.append("left")
        if c1 == w - 1: edges.append("right")
        if len(edges) != 2 or set(edges) not in (
            {"top", "left"}, {"top", "right"},
            {"bottom", "left"}, {"bottom", "right"}
        ):
            continue

        # Junction is the bbox corner away from the two touched edges.
        jr = r1 if "top" in edges else r0
        jc = c1 if "left" in edges else c0
        if (jr, jc) not in cells:
            continue

        # Require the component to be an L: substantial straight arms
        # from the junction along both bbox dimensions.
        row_arm = sum((jr, x) in cells for x in range(c0, c1 + 1))
        col_arm = sum((y, jc) in cells for y in range(r0, r1 + 1))
        if row_arm < 2 or col_arm < 2:
            continue
        marker = (color, cells, (jr, jc), (r0, r1, c0, c1))
        break

    if marker is None:
        return [row[:] for row in grid]

    color, marker_cells, (jr, jc), (r0, r1, c0, c1) = marker
    # The target lies in the open quadrant opposite the two arms.
    row_sign = -1 if jr == r1 else 1
    col_sign = -1 if jc == c1 else 1

    best = None
