        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        cr = sum(rs) / len(rs)
        cc = sum(cs) / len(cs)
        if (cr - jr) * row_sign <= 0 or (cc - jc) * col_sign <= 0:
            continue

        if row_sign < 0:
            dr = max(0, jr - max(rs))
        else:
            dr = max(0, min(rs) - jr)
        if col_sign < 0:
            dc = max(0, jc - max(cs))
        else:
            dc = max(0, min(cs) - jc)
        score = dr + dc
        if best is None or score < best[0]:
            best = (score, cells)

    out = [row[:] for row in grid]
    if best:
        for r, c in best[1]:
            out[r][c] = color
    return out
